def if_in_default_of_switch(
    kind: aas_types.Kind,
    number: int
) -> bool:
    """
    Check the ``elif`` which does not compare the subject of the switch.

    The ``elif`` becomes an if-statement in the default of the switch, and nests
    a switch in turn.
    """
    # pylint: disable=all
    if kind == aas_types.Kind.ALPHA:
        return number < 10
    else:
        if number < -5:
            if kind == aas_types.Kind.BETA:
                return False
    return True


