def if_with_reassigned_variable(
    number: int
) -> bool:
    """
    Check the variable defined before the if-statement and assigned in it.
    """
    # pylint: disable=all
    result = 0
    if (
        (
            number > 20
            and number < 30
        )
    ):
        result = number
    elif number < -20:
        result = -number
    return result < 25


def if_with_continue_in_for(
    number: int
) -> bool:
    """
    Check the ``continue`` in a branch of an if-statement nested in a for-loop.
    """
    # pylint: disable=all
    count = 0
    for i in range(0, 10):
        if (
            (
                (i % 2) == (0)
                or i > number
            )
        ):
            continue
        count = count + 1
    return count != 3


